package com.tripcraft.service;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.math.RoundingMode; import java.util.*;
@Service public class PlanBuilderService { private final JdbcTemplate db; public PlanBuilderService(JdbcTemplate db){this.db=db;}
  public List<Map<String,Object>> build(BigDecimal budget,int people,int days,String destination){String like=destination==null?"%":"%"+destination+"%";List<Map<String,Object>> rows=db.queryForList("SELECT p.id,p.title,p.duration_days durationDays,p.price_per_person price,d.name destinationName,p.image_url imageUrl FROM packages p JOIN destinations d ON d.id=p.destination_id WHERE p.active=1 AND d.name LIKE ? AND p.duration_days<=? ORDER BY p.price_per_person",like,days);if(rows.isEmpty()&&destination!=null)rows=db.queryForList("SELECT p.id,p.title,p.duration_days durationDays,p.price_per_person price,d.name destinationName,p.image_url imageUrl FROM packages p JOIN destinations d ON d.id=p.destination_id WHERE p.active=1 AND p.duration_days<=? ORDER BY p.price_per_person",days);List<Map<String,Object>> candidates=new ArrayList<>();for(Map<String,Object> row:rows){BigDecimal total=((BigDecimal)row.get("price")).multiply(BigDecimal.valueOf(people));if(total.compareTo(budget)<=0){Map<String,Object>x=new LinkedHashMap<>(row);x.put("estimatedTotal",total);x.put("remainingBalance",budget.subtract(total));x.put("stayEstimate",total.multiply(new BigDecimal(".45")).setScale(2,RoundingMode.HALF_UP));x.put("transportEstimate",total.multiply(new BigDecimal(".2")).setScale(2,RoundingMode.HALF_UP));x.put("placesEstimate",total.multiply(new BigDecimal(".15")).setScale(2,RoundingMode.HALF_UP));x.put("foodEstimate",total.multiply(new BigDecimal(".2")).setScale(2,RoundingMode.HALF_UP));candidates.add(x);}}List<Map<String,Object>> out=new ArrayList<>();pickClosest(candidates,budget.multiply(new BigDecimal(".70")),out);pickClosest(candidates,budget.multiply(new BigDecimal(".90")),out);pickClosest(candidates,budget,out);return out;}
  private void pickClosest(List<Map<String,Object>> candidates,BigDecimal target,List<Map<String,Object>> chosen){Map<String,Object> best=null;BigDecimal distance=null;for(Map<String,Object> c:candidates){if(chosen.stream().anyMatch(x->Objects.equals(x.get("id"),c.get("id"))))continue;BigDecimal d=((BigDecimal)c.get("estimatedTotal")).subtract(target).abs();if(distance==null||d.compareTo(distance)<0){best=c;distance=d;}}if(best!=null)chosen.add(best);}
}
